CREATE TABLE idempotency_record(actor_id BIGINT NOT NULL,operation VARCHAR(40) NOT NULL,request_key VARCHAR(80) NOT NULL,request_hash CHAR(64) NOT NULL,response_json JSON NOT NULL,PRIMARY KEY(actor_id,operation,request_key));
CREATE TABLE outbox_event(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id CHAR(36) NOT NULL UNIQUE,target VARCHAR(40) NOT NULL,event_type VARCHAR(60) NOT NULL,payload JSON NOT NULL,status VARCHAR(20) NOT NULL,retry_count INT NOT NULL DEFAULT 0,next_retry_at DATETIME(3) NOT NULL,lease_until DATETIME(3),published_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX ix_dispatch(status,next_retry_at));
CREATE TABLE consumed_event(event_id CHAR(36) PRIMARY KEY,consumed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT,action VARCHAR(60) NOT NULL,resource_id VARCHAR(60),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));

CREATE TABLE trade_order(reservation_id BIGINT PRIMARY KEY,user_id BIGINT NOT NULL,prepay_fen BIGINT NOT NULL,overtime_fen BIGINT NOT NULL DEFAULT 0,paid_prepay_fen BIGINT NOT NULL DEFAULT 0,paid_overtime_fen BIGINT NOT NULL DEFAULT 0,refund_fen BIGINT NOT NULL DEFAULT 0,status VARCHAR(24) NOT NULL DEFAULT 'WAIT_PAY',version INT NOT NULL DEFAULT 0);
CREATE TABLE payment_attempt(id BIGINT PRIMARY KEY,reservation_id BIGINT NOT NULL,user_id BIGINT NOT NULL,kind VARCHAR(16) NOT NULL,amount_fen BIGINT NOT NULL,status VARCHAR(20) NOT NULL,channel_no VARCHAR(80) NOT NULL UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX ix_work(status,created_at),FOREIGN KEY(reservation_id) REFERENCES trade_order(reservation_id));
CREATE TABLE channel_operation(channel_no VARCHAR(80) PRIMARY KEY,kind VARCHAR(16) NOT NULL,amount_fen BIGINT NOT NULL,result VARCHAR(20) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE ledger_entry(id BIGINT AUTO_INCREMENT PRIMARY KEY,reservation_id BIGINT NOT NULL,channel_no VARCHAR(80) NOT NULL UNIQUE,kind VARCHAR(16) NOT NULL,amount_fen BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
